// tokenbucket.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is injectable time source.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token bucket.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// NewTokenBucket creates a bucket with the given capacity and refill rate.
// A nil clock uses the system clock.
func NewTokenBucket(capacity int, ratePerSecond float64, clock Clock) (*TokenBucket, error) {
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if ratePerSecond <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &TokenBucket{
		capacity: float64(capacity),
		rate:     ratePerSecond,
		tokens:   float64(capacity),
		last:     now,
		clock:    clock,
	}, nil
}

func (b *TokenBucket) refillLocked(now time.Time) {
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
}

// AllowN reports whether n tokens can be consumed, deducting them if so.
// n <= 0 is always allowed.
func (b *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	now := b.clock.Now()
	b.refillLocked(now)
	if float64(n) > b.capacity {
		return false
	}
	if b.tokens >= float64(n) {
		b.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token can be consumed.
func (b *TokenBucket) Allow() bool { return b.AllowN(1) }

// Tokens returns the current estimated available tokens.
func (b *TokenBucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked(b.clock.Now())
	return b.tokens
}
