	tests := []struct {
		name    string
		cap     int
		rate    float64
		advance time.Duration
		n       int
		want    bool
	}{
		{"full bucket allows one", 5, 1, 0, 1, true},
		{"zero n always allowed", 5, 1, 0, 0, true},
		{"negative n always allowed", 5, 1, 0, -2, true},
		{"n exceeds capacity denied", 5, 1, 0, 6, false},
		{"refill allows after delay", 10, 10, 100 * time.Millisecond, 1, true},
		{"refill insufficient denied", 10, 10, 50 * time.Millisecond, 1, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clock := newFakeClock(time.Unix(0, 0))
			b, err := NewTokenBucket(tt.cap, tt.rate, clock)
			if err != nil {
				t.Fatal(err)
			}
			if tt.advance > 0 {
				clock.Advance(tt.advance)
			}
			if got := b.AllowN(tt.n); got != tt.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tt.n, got, tt.want)
			}
		})
	}
}

func TestAllowNDrainsAndRefills(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	b, err := NewTokenBucket(2, 1, clock)
	if err != nil {
		t.Fatal(err)
	}
	if !b.AllowN(2) {
		t.Fatal("expected first AllowN(2) to succeed")
	}
	if b.AllowN(1) {
		t.Fatal("expected bucket to be empty")
	}
	clock.Advance(1500 * time.Millisecond)
	if !b.AllowN(1) {
		t.Fatal("expected refill to allow one token")
	}
}

func TestAllowNConcurrent(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	b, err := NewTokenBucket(100, 0.0001, clock)
	if err != nil {
		t.Fatal(err)
	}
	var allowed atomic.Int32
	var wg sync.WaitGroup
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.Allow() {
				allowed.Add(1)
			}
		}()
	}
	wg.Wait()
	if got := allowed.Load(); got != 100 {
		t.Fatalf("allowed = %d, want 100", got)
	}
}
