func TestNewValidation(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 1, 1, nil, true},
		{"zero capacity", 0, 1, clk, true},
		{"negative capacity", -1, 1, clk, true},
		{"zero rate", 1, 0, clk, true},
		{"negative rate", 1, -1, clk, true},
		{"valid", 5, 2.5, clk, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b, err := New(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tt.wantErr)
			}
			if !tt.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	tests := []struct {
		name   string
		cap    int
		rate   float64
		advance time.Duration
		n      int
		want   bool
	}{
		{"full bucket allows capacity", 5, 1, 0, 5, true},
		{"over capacity never allowed", 5, 1, 0, 6, false},
		{"zero tokens allowed", 5, 1, 0, 0, true},
		{"refill after advance", 2, 2, 500 * time.Millisecond, 1, true},
		{"fractional refill", 10, 10, 150 * time.Millisecond, 1, true},
		{"refill capped at capacity", 2, 100, time.Second, 2, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clk := newFakeClock(base)
			b, err := New(tt.cap, tt.rate, clk)
			if err != nil {
				t.Fatal(err)
			}
			if tt.advance > 0 {
				clk.Advance(tt.advance)
			}
			if got := b.AllowN(tt.n); got != tt.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tt.n, got, tt.want)
			}
		})
	}
}

func TestAllowConsumesAndRefills(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	b, err := New(2, 2, clk)
	if err != nil {
		t.Fatal(err)
	}
	if !b.AllowN(2) {
		t.Fatal("expected initial allow")
	}
	if b.AllowN(1) {
		t.Fatal("expected empty bucket")
	}
	clk.Advance(500 * time.Millisecond)
