	}
	if b.AllowN(1) {
		t.Fatal("expected only one refilled token")
	}
}

func TestConcurrentAllow(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	b, err := New(50, 0.001, clk)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0
	for i := 0; i < 100; i++ {
		wg.Add(1)
